/**
 * Refresh the litter counters on the page
 */
var cp_litter_counter_page_time  = new Date().getTime() / 1000;
var cp_litter_counter_debug = false;

jQuery('.cp-litter-counter').each(function() {

    var element = this;
    var litter_counter_refresh = (jQuery(element).data('cp-litter-counter-refresh')) ? jQuery(element).data('cp-litter-counter-refresh') : 5000;
    var update_counter         = (jQuery(element).data('cp-litter-counter-update') && jQuery(element).data('cp-litter-counter-update') === 'false') ? false : true;

    if ( update_counter === true ) {

        setInterval(function (element) {

            catsprideConsoleLog('Updating counter...');

            var litter_counter_page_time_now = new Date().getTime() / 1000;
            var litter_counter_rate = parseFloat(jQuery(element).data('cp-litter-counter-rate'));
            var litter_counter_total = parseInt(jQuery(element).data('cp-litter-counter-total'));
            var comparison_time = (jQuery(element).data('cp-litter-counter-last-refresh-time')) ? jQuery(element).data('cp-litter-counter-last-refresh-time') : cp_litter_counter_page_time;

            // Seconds since last counter refresh
            var seconds = parseInt(litter_counter_page_time_now - comparison_time);

            // New total to set the counter to
            var new_total = Math.round(seconds * litter_counter_rate + litter_counter_total);

            if( new_total <= litter_counter_total) {
                return;
            }

            catsprideConsoleLog('Rate of Increase per second: ' + litter_counter_rate);
            catsprideConsoleLog('Current Total: ' + litter_counter_total);
            catsprideConsoleLog('Seconds since last refresh: ' + seconds);
            catsprideConsoleLog('New Total: ' + new_total);

            // Update data property values
            catsprideConsoleLog('Updating the data attribs on the element...');
            jQuery(element).data('cp-litter-counter-total', new_total);
            jQuery(element).data('cp-litter-counter-last-refresh-time', litter_counter_page_time_now);

            jQuery(element).prop('Counter', litter_counter_total).animate({
                Counter: new_total
            }, {
                duration: 1000,
                easing: 'swing',
                step: function (number) {
                    jQuery(this).find('.cp-litter-counter-total').text(catsprideAddCommasToNumber(parseInt(number)));
                }
            });

        }, litter_counter_refresh, element);

    }

});

/**
 * Handles conditionally visible fields
 */
jQuery('[data-depends-on-selector]').each( function() {

    var selectorName  = jQuery(this).data('depends-on-selector');
    var selectorValue = jQuery(this).data('depends-on-value');

    jQuery(selectorName).on('change', {'selector': selectorName, 'value': selectorValue }, function( e ) {

        var selectorType = jQuery(e.data.selector).attr('type');

        if ( selectorType === 'radio' || selectorType === 'checkbox' ) {
            var valueSelector = e.data.selector + ':checked';
        } else {
            var valueSelector = e.data.selector;
        }

        var selectorTarget = '[data-depends-on-selector="' + e.data.selector + '"]';
        var valueTarget = '[data-depends-on-value="' + e.data.value + '"]';

        if ( jQuery(valueSelector).val() == e.data.value ) {
            jQuery(selectorTarget).filter(valueTarget).show().find(':input').attr('disabled', false);
        } else {
            var inputs = jQuery(selectorTarget).filter(valueTarget).hide().find(':input');
            inputs.attr('disabled', true);
            inputs.filter('[type="text"], textarea, select').val(null);
            inputs.filter('[type="radio"]').attr('checked', false);
            inputs.trigger('change');
        }
    });

    jQuery(selectorName).trigger('change');

});

