function catsprideConsoleLog( message ) {
    if(cp_litter_counter_debug !== false) {
        console.log(message);
    }
}

function catsprideAddCommasToNumber( number )
{
    number += '';
    x = number.split('.');
    x1 = x[0];
    x2 = x.length > 1 ? '.' + x[1] : '';
    var rgx = /(\d+)(\d{3})/;
    while (rgx.test(x1)) {
        x1 = x1.replace(rgx, '$1' + ',' + '$2');
    }
    return x1 + x2;
}


const tabButtons = document.querySelectorAll('.tab-btn');
const tabContents = document.querySelectorAll('.tab-content');

tabButtons.forEach(button => {
  button.addEventListener('click', () => {
    // Remove active class from all buttons and contents
    tabButtons.forEach(btn => btn.classList.remove('active'));
    tabContents.forEach(content => content.classList.remove('active'));

    // Add active class to clicked button and matching content
    button.classList.add('active');
    document.getElementById(button.dataset.tab).classList.add('active');
  });
});


document.addEventListener('DOMContentLoaded', function () {
    const radioButtons = document.querySelectorAll('input[name="page_header_type"]');
    const slideshowDiv = document.querySelector('.shelter-page-header-type-slideshow');
    const videoDiv = document.querySelector('.shelter-page-header-type-video');

    function updateVisibility() {
        const selectedValue = document.querySelector('input[name="page_header_type"]:checked')?.value;
        if (slideshowDiv) {
            slideshowDiv.style.display = selectedValue === 'slideshow' ? 'block' : 'none';
        }
        if (videoDiv) {
            videoDiv.style.display = selectedValue === 'video' ? 'block' : 'none';
        }
    }

    if (radioButtons.length > 0 || slideshowDiv || videoDiv) {
        radioButtons.forEach(radio => {
            radio.addEventListener('change', updateVisibility);
        });

        // Set initial visibility
        updateVisibility();
    }
});